<?php
namespace App\Http\Controllers\Tenant;
use App\Http\Controllers\Controller; use App\Http\Requests\SaveDiscountRequest; use App\Models\Discount; use Illuminate\Http\Request; use Illuminate\Http\JsonResponse;
readonly class DiscountController extends Controller { public function index(){return view('tenant.discounts.index',['types'=>Discount::typeOptions(),'targets'=>Discount::appliesToOptions()]);} public function listing(Request $r): JsonResponse { $q=Discount::query(); if($s=trim((string)$r->input('search.value')))$q->where(fn($x)=>$x->where('name','like',"%$s%")->orWhere('code','like',"%$s%")); $total=Discount::count(); $rows=$q->latest()->skip((int)$r->input('start',0))->take((int)$r->input('length',10))->get(); return response()->json(['draw'=>(int)$r->input('draw'),'recordsTotal'=>$total,'recordsFiltered'=>$q->count(),'data'=>$rows]);} public function show(Discount $discount): JsonResponse{return response()->json($discount);} public function save(SaveDiscountRequest $r): JsonResponse { $d=$r->filled('id')?Discount::findOrFail($r->id):new Discount; $d->fill($r->safe()->except(['id'])); $d->created_by ??= auth()->id(); $d->updated_by=auth()->id(); $d->save(); return response()->json(['message'=>'Discount saved.','discount'=>$d]); } public function destroy(Discount $d): JsonResponse{$d->delete();return response()->json(['message'=>'Discount deleted.']);} }
